function url(file,extras={}){const q=new URLSearchParams();if(language==='ur')q.set('lang','ur');const closed=data.reviews.filter(r=>doneIds.includes(r.id)||(r.savedHere)).map(r=>r.id);if(closed.length)q.set('done',closed.join(','));if(siteFilter!=='all')q.set('site',siteFilter);for(const[k,v]of Object.entries(extras))q.set(k,v);return file+'.html'+(q.size?'?'+q:'')}
